import math


def poly(xs: list, x: float):
    """Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + ... + xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    The polynomial must have an odd degree (even number of coefficients)
    so it is guaranteed to have at least one real root.
    """
    def f(x):
        return poly(xs, x)

    # Try small symmetric interval first
    low, high = -1.0, 1.0
    while f(low) * f(high) > 0:
        low *= 2
        high *= 2
        # Safeguard against infinite loops
        if abs(low) > 1e12 or abs(high) > 1e12:
            break

    # If still same sign, use a huge symmetric interval
    if f(low) * f(high) > 0:
        low, high = -1e12, 1e12

    # Bisection method
    for _ in range(200):
        mid = (low + high) / 2.0
        fm = f(mid)
        if abs(fm) < 1e-12:
            return mid
        if f(low) * fm < 0:
            high = mid
        else:
            low = mid

    return (low + high) / 2.0
