def is_simple_power(x, n):
    """Return True if x is a simple power of n, i.e. x = n**k for some integer k."""
    # Handle special cases
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1

    # 1 is always a power (k = 0)
    if x == 1:
        return True

    # Search for an integer exponent k >= 1
    power = n
    # Use absolute values to avoid endless loops when n<-1 keeps oscillating
    while abs(power) <= abs(x):
        if power == x:
            return True
        power *= n
    return False
